(()=>{'use strict';const sheet=document.getElementById('save-sheet');let opener=null,pending=null;const previousMedia=window.omniMediaController,previousPad=window.omniPadController;const targets=()=>[...sheet.querySelectorAll('button')].filter(e=>!e.disabled);function dismiss(action){if(!sheet.open)return false;const result=pending;pending=null;sheet.close();if(opener?.isConnected)opener.focus();if(result?.callback)result.callback({requestId:result.requestId,action});return true}function show(context={},callback){if(sheet.open)dismiss('dismiss');opener=document.activeElement;pending={requestId:String(context.requestId||''),callback:typeof callback==='function'?callback:null};document.getElementById('save-origin').textContent=String(context.originLabel||'This site');document.getElementById('save-detail').textContent=String(context.usernameLabel||'Saved login')+' · ••••••••••••';sheet.showModal();document.getElementById('sheet-save').focus()}function handle(action){if(!sheet.open)return false;action=String(action).toLowerCase();const all=targets(),i=all.indexOf(document.activeElement);if(['left','up','right','down','l1','r1'].includes(action)){const direction=['left','up','l1'].includes(action)?-1:1;all[(i+direction+all.length)%all.length].focus();return true}if(['cross','a','accept','confirm'].includes(action)){if(all.includes(document.activeElement))document.activeElement.click();return true}if(['circle','b','back'].includes(action))return dismiss('dismiss');return false}window.obPasswordOverlay={open:show,close:()=>dismiss('dismiss'),handle};window.omniMediaController=a=>sheet.open?handle(a):previousMedia?.(a)||false;window.omniPadController=a=>sheet.open?handle(a):previousPad?.(a)||false;sheet.addEventListener('cancel',e=>{e.preventDefault();dismiss('dismiss')});document.addEventListener('keydown',e=>{if(!sheet.open)return;if(e.key==='Tab'){const a=targets(),i=a.indexOf(document.activeElement);e.preventDefault();a[(i+(e.shiftKey?-1:1)+a.length)%a.length].focus();return}const action={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Escape:'circle'}[e.key];if(action&&handle(action))e.preventDefault()});document.getElementById('sheet-save').onclick=()=>dismiss('save');document.getElementById('sheet-never').onclick=()=>dismiss('never');document.getElementById('sheet-dismiss').onclick=()=>dismiss('dismiss');document.getElementById('show-prompt').onclick=()=>show({requestId:'demo-1',originLabel:'example.com',usernameLabel:'demo@example.com'},result=>{document.getElementById('overlay-notice').textContent=result.action==='dismiss'?'Prompt dismissed.':'Preview choice: '+result.action+'. No credential was stored.'});document.getElementById('show-prompt').focus()})();